import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { before, after, test } from 'node:test';
import { createServer, request } from 'node:http';
import type { AddressInfo } from 'node:net';
import express from 'express';
import { ObjectId } from 'mongodb';
import { getDatabaseClient, getDb } from '../../src/infrastructure/database';
import { asyncHandler, limitConcurrency } from '../../src/middleware/requestProtectionMiddleware';
import { ServerLifecycle } from '../../src/services/platform/serverLifecycleService';
import { createAdminImport, initializeAdminImportStorage } from '../../src/administration/import/adminImportService';
import { MetadataLookupSourceError } from '../../src/administration/lookup/lookupContract';
import type { MetadataLookupRecord } from '../../src/administration/lookup/metadataLookupRecord';
import { adminImportLookupCollection, requestAutomaticMetadataLookup, startMetadataLookupWorker } from '../../src/administration/lookup/metadataLookupService';
import { createMusicBrainzClient, type MusicBrainzClient } from '../../src/administration/lookup/musicBrainzClient';
import { emptyItunesClient, fixtureTransport, immediateGate } from '../support/metadataLookupFixtures';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness;
before(async () => { harness = await startMongoReplicaSet('archtree-shutdown-tests'); });
after(async () => { await harness?.stop(); });

test('disconnected HTTP transaction retains capacity and commits before graceful database teardown', async () => {
  const db = getDb()!;
  await db.createCollection('shutdownFixture');
  const lifecycle = new ServerLifecycle();
  const app = express();
  app.use(lifecycle.admit);
  let finish!: () => void;
  let entered!: () => void;
  const workGate = new Promise<void>(resolve => { finish = resolve; });
  const written = new Promise<void>(resolve => { entered = resolve; });
  let cleanupStarted = false;
  app.post('/mutation', limitConcurrency('shutdown-transaction', 1, 1), asyncHandler(async (req, res) => {
    req.resume();
    const session = getDatabaseClient().startSession();
    try {
      await session.withTransaction(async () => {
        await db.collection('shutdownFixture').insertOne({ value: 'synthetic' }, { session });
        entered();
        await workGate;
      });
    } finally { await session.endSession(); }
    res.end();
  }));
  const server = app.listen(0, '127.0.0.1');
  await new Promise<void>(resolve => server.once('listening', resolve));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/mutation`;
  const req = request(url, { method: 'POST' });
  req.on('error', () => undefined);
  req.end();
  try {
    await written;
    const closed = new Promise<void>(resolve => req.once('close', resolve));
    req.destroy();
    await closed;
    const rejected = await fetch(url, { method: 'POST' });
    assert.equal(rejected.status, 429);
    await rejected.text();
    const stopping = lifecycle.stop(server, async () => {
      cleanupStarted = true;
      assert.equal(await db.collection('shutdownFixture').countDocuments({}), 1);
    }, 2_000, 1_000);
    await new Promise(resolve => setTimeout(resolve, 25));
    assert.equal(cleanupStarted, false);
    assert.equal(await db.collection('shutdownFixture').countDocuments({}), 0);
    finish();
    assert.equal(await stopping, 'graceful');
    assert.equal(cleanupStarted, true);
  } finally { finish(); req.destroy(); server.closeAllConnections(); server.close(); }
});

test('draining waits for a tracked metadata lookup pass, which aborts its request and releases its lease before database teardown', async () => {
  const environment = { FINITUDE_ADMIN_IMPORTS_ENABLED: 'true', FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY: 'true',
    ADMIN_IMPORT_S3_BUCKET_NAME: 'synthetic-private-imports', FINITUDE_ADMIN_METADATA_LOOKUP_CONTACT: 'shutdown-operator@example.test' };
  Object.assign(process.env, environment);
  const server = createServer();
  try {
    const db = getDb()!, admin = new ObjectId(), by = admin.toHexString(), slotId = randomUUID(), operationId = randomUUID();
    await db.collection('users').insertOne({ _id: admin, email: 'shutdown-admin@example.test', role: 'admin' });
    await initializeAdminImportStorage(db);
    const item = (await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Folder',
      files: [{ slotId, filename: '01 Synthetic.wav', relativePath: 'Synthetic Folder/01 Synthetic.wav', byteLength: null }] } })).item;
    // One confirmed file with shared album tags, written directly, so the trigger queues a run without storage.
    const tags = { version: 2, title: null, album: 'Synthetic Album', artists: [], albumArtists: ['Synthetic Ensemble'], label: null, year: null, discNumber: null,
      trackNumber: null, durationMs: 1000, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null }, flagged: [] };
    await db.collection('adminAlbumImports').updateOne({ _id: new ObjectId(item.id) }, { $set: { media: { assets: [{ slotId, operationId, actorId: by,
      bucket: 'synthetic-private-imports', key: `imports/${item.id}/${slotId}/${operationId}`, sha256: 'a'.repeat(64), byteLength: 10, contentType: 'audio/wav',
      filename: '01 Synthetic.wav', state: 'ready', versionId: 'stage-version', etag: '"stage-etag"', updatedAt: new Date(), leaseOwner: null, leaseUntil: null,
      transferDeadline: null, failureConfirmedAt: null, duration: '0:01', format: 'wav', representation: null, tags, automatedAt: new Date(),
      recovery: { operationId, expectedRevision: 1, kind: 'upload', actorId: by } }] } } });
    assert.equal((await requestAutomaticMetadataLookup(by, item.id, 'upload')).reason, 'queued');

    // The first search stays in flight until its signal aborts; nothing reaches a transport.
    let entered!: () => void, aborted = false;
    const inFlight = new Promise<void>(resolve => { entered = resolve; });
    const base = createMusicBrainzClient({ gate: immediateGate(), transport: fixtureTransport([]).transport, sleep: async () => undefined });
    const holding: MusicBrainzClient = { ...base, searchReleases: (_query, options) => {
      entered();
      return new Promise((_resolve, reject) => options.signal.addEventListener('abort', () => { aborted = true; reject(new MetadataLookupSourceError('musicbrainz', 'cancelled')); }, { once: true }));
    } };
    const lifecycle = new ServerLifecycle();
    const stopWorker = startMetadataLookupWorker({ musicBrainz: holding, itunes: emptyItunesClient() }, 10, operation => lifecycle.track(operation));
    lifecycle.onDrain(() => { void stopWorker(); });
    server.listen(0, '127.0.0.1');
    await new Promise<void>(resolve => server.once('listening', resolve));
    await inFlight;
    const running = (await adminImportLookupCollection().findOne({ _id: new ObjectId(item.id) }))!;
    assert.deepEqual([running.state, typeof running.leaseOwner, running.queryIndex], ['running', 'string', 0]);

    let atTeardown: MetadataLookupRecord | null = null;
    const outcome = await lifecycle.stop(server, async () => { atTeardown = await adminImportLookupCollection().findOne({ _id: new ObjectId(item.id) }); }, 2_000, 1_000);
    assert.equal(outcome, 'graceful');
    assert.equal(aborted, true);
    // The pass settled before teardown: its lease is released and the run resumes at the stored step.
    const paused = atTeardown as MetadataLookupRecord | null;
    assert.deepEqual([paused?.state, paused?.leaseOwner, paused?.leaseUntil, paused?.queryIndex, paused?.candidates], ['running', null, null, 0, []]);
  } finally {
    if (server.listening) server.close();
    for (const name of Object.keys(environment)) delete process.env[name];
  }
});
